/* Calculator procedures use the non-CAS TI-Nspire CX II. Menu labels may vary by OS. */
const CALC_GUIDES={
 basic:{name:'Accurate calculation and display',ti84:['Press MODE; choose FLOAT for calculations and check DEGREE or RADIAN before trigonometry.','Use the (−) key for negative numbers and brackets around negative bases. Use 2nd then the comma key (EE) for scientific notation.','Keep the full stored value when continuing a calculation. Round only the final answer to the required accuracy.'],nspire:['Start a Calculator page. In Document Settings check angle mode and use a floating display.','Use the negative sign for a negative value, brackets around bases, and the EE key for scientific notation.','Use the previous result or a stored variable to preserve accuracy; round the final reported answer.'],video:'Calculator Home Screen'},
 graph:{name:'Graph a model and read its values',ti84:['Press Y=, clear old equations and enter the model using X,T,θ,n for x.','Press WINDOW and set Xmin/Xmax to the domain in the question, then choose useful Ymin/Ymax. Press GRAPH.','Press 2nd TRACE (CALC), choose value and enter the desired x. For a table use 2nd WINDOW (TBLSET), then 2nd GRAPH (TABLE).','Record a labelled sketch and the model, not just the screen output.'],nspire:['Add a Graphs page and enter the expression in f1(x).','Use menu → Window/Zoom → Window Settings to show the requested domain and a useful y interval.','Use menu → Trace → Graph Trace, then type the required x and press enter. Use menu → Table to view a value table.','Write the model and a labelled sketch with intercepts and relevant domain.'],video:'Graphs'},
 intersection:{name:'Solve an equation numerically',ti84:['Enter the two sides as Y1 and Y2 in Y=. For a root you can enter one side minus the other and compare with zero.','Choose a window showing the required solutions, then press GRAPH.','Press 2nd TRACE → intersect. Select the first and second curves with ENTER, move near the intersection and confirm the guess. Repeat for other intersections.','For a root use zero instead; supply left bound, right bound and a guess. Check every result in the original equation.'],nspire:['Add a Graphs page and enter both functions. Set an appropriate window.','Use menu → Analyze Graph → Intersection. Select the lower and upper bounds around a single intersection.','Repeat around other intersections. For f(x)=0 use Analyze Graph → Zero.','Retain solutions in the contextual domain and write the equation solved.'],video:'Graphs'},
 minimum:{name:'Locate a turning point',ti84:['Enter the function in Y= and press GRAPH using a useful window.','Press 2nd TRACE → minimum or maximum as appropriate.','Move to a point left of the turning point and press ENTER; repeat to the right, then give a nearby guess.','Record both coordinates. On a restricted interval also evaluate endpoints; a local turning point need not be the global optimum.'],nspire:['Enter the function on a Graphs page and set the window.','Use menu → Analyze Graph → Minimum or Maximum.','Choose bounds around the required turning point and read both coordinates.','Check endpoints separately when the model has a closed domain.'],video:'Graphs'},
 regression:{name:'Fit and interpret a regression',ti84:['Press STAT → Edit. Enter x values in L1 and paired y values in L2. To clear an old list, highlight its heading, press CLEAR then ENTER; do not delete the list name.','Enable Stat Diagnostics in MODE if r is not displayed. Press 2nd Y= for Stat Plot, turn Plot1 ON and choose the scatter icon with Xlist L1 and Ylist L2. Use ZOOM → ZoomStat.','Press STAT → CALC. Choose LinReg(ax+b), QuadReg, CubicReg or the model required. Set Xlist L1, Ylist L2 and Store RegEQ Y1 (VARS → Y-VARS → Function → Y1).','Calculate, record coefficients and correlation where relevant, then check predictions using the stored Y1 rather than rounded coefficients. For Spearman rank the data first, including tied average ranks.'],nspire:['Add Lists & Spreadsheet. Name columns xs and ys and enter paired values.','Use menu → Statistics → Stat Calculations and select the required regression model.','Set X List xs, Y List ys, and Save RegEqn To f1. Confirm and read coefficients and correlation.','Plot the data in Data & Statistics and check the model. Evaluate f1(input) on a Calculator page; use ranked lists for Spearman.'],video:'Lists and Spreadsheet'},
 sequence:{name:'Sequences, iteration and sums',ti84:['On the home screen enter the nth-term formula using a numerical n, or store the expression in Y1 for a table.','For a sum, use 2nd STAT (LIST) → OPS → seq to generate the terms, then LIST → MATH → sum. Write the term formula with its index bounds.','For Euler steps make a table of current time, old value, old slope and next value. Calculate all next values from the old row.','Check the first term carefully: the nth term often uses n−1, not n.'],nspire:['Use a Calculator page for the explicit nth-term formula. Use the Catalog to insert sum or sequence with the stated index bounds.','For a table, add Lists & Spreadsheet and calculate terms from an index column.','For Euler steps create columns for time, old value and next value; in coupled equations all updated values must reference the same old row.','Check initial values and state the step size for numerical approximations.'],video:'Calculator'},
 finance:{name:'Finance / TVM solver',ti84:['Press APPS → Finance → TVM Solver. Identify N, I%, PV, PMT, FV, P/Y and C/Y.','N is the total number of payments; I% is the nominal annual percentage. Set payments per year and compounding per year separately.','Use opposite signs for money received and money paid. Choose END for end-of-period payments unless the question states BEGIN.','Place the cursor on the unknown and press ALPHA ENTER (SOLVE). Report the magnitude and explain the cash-flow sign.'],nspire:['Add a Calculator page. Use menu → Finance → Finance Solver.','Enter total payment count, annual interest percentage, present/future values and payment as appropriate.','Set payments/year, compounding/year and beginning/end timing. Cash received and paid should have opposite signs.','Select the unknown and solve. Verify the result fits the context and units.'],video:'Calculator'},
 trig:{name:'Trigonometry, angles and sectors',ti84:['Press MODE and choose DEGREE for bearings and degree angles, or RADIAN for radian models.','Use SIN/COS/TAN and 2nd with the corresponding key for an inverse trig function.','Put a complete numerator and denominator in brackets; use the square-root template for the cosine-rule side length.','For sine models check the period in the chosen mode. SinReg output is a radian model: do not interpret its coefficients as degrees.'],nspire:['Use Document Settings → Angle and set degrees or radians to match the problem.','Use trig keys or Catalog for sin, cos, tan and inverses.','Use fraction and square-root templates to avoid missing brackets.','Check a triangle angle sum or known special angle. Regression sine models use radians; verify units.'],video:'Graphs'},
 geometry:{name:'Geometry and measurement',ti84:['Draw a labelled diagram on paper and convert all dimensions to one unit.','Enter the area or volume formula on the home screen; use 2nd ^ for π.','For a bisector or coordinate model, enter the resulting equation in Y= to inspect it.','Do not infer precise distances from screen appearance; report correct squared/cubed units.'],nspire:['Make a labelled sketch and choose consistent units.','Evaluate the formula on a Calculator page, using π from the symbols.','A Graphs or Geometry page can illustrate a line or perpendicular bisector; confirm values using the equation.','State whether the model assumes a plane and a straight-line distance metric.'],video:'Geometry'},
 matrix:{name:'Matrices and transition models',ti84:['Press 2nd x⁻¹ (MATRIX) → EDIT. Choose [A], set its dimensions, and fill entries row by row. Repeat for [B] when needed.','On the home screen insert matrices from MATRIX → NAMES. Use [A]⁻¹*[B] for an invertible linear system or [A]^n*[B] for n transition steps.','Use MATRIX → MATH → det for the determinant. If zero, an inverse does not exist.','For transition matrices state the row/column convention and verify the corresponding sums equal 1.'],nspire:['On a Calculator page insert a matrix using the Templates key; set dimensions and enter rows. Store as a.','Enter a^(-1)*b for an invertible system or a^n*b for transition steps. Use menu → Matrix & Vector for determinant and matrix operations.','Check dimensions and determinant before inversion.','The vector convention determines multiplication order; interpret the returned state values.'],video:'Calculator'},
 vector:{name:'Vector components and scalar product',ti84:['Use lists or a column matrix to represent components consistently.','For a dot product, multiply corresponding components and sum them. You can use sum(L1*L2) for matching component lists.','Compute magnitudes using square roots of sums of squared components. Use inverse cosine of dot/(magnitude product) for the angle.','For vector motion, calculate each coordinate using the same parameter/time. This guide does not use a vector product.'],nspire:['Use list or matrix templates for component vectors.','Use dotP from the Catalog or Matrix & Vector menu for the scalar product, and norm for a vector magnitude.','Use inverse cosine of the scalar product divided by the two norms to obtain an angle.','Keep the same time parameter in every motion coordinate and check all collision equations.'],video:'Calculator'},
 network:{name:'Graph-theory calculations',ti84:['Draw the network on paper and label every edge weight.','Use the calculator only to add candidate route weights and compare totals; do not assume it finds an optimal route.','Keep an algorithm table: visited vertices and tentative distances for Dijkstra, or chosen edges for Kruskal.','For route inspection list odd vertices and compare complete pairings, not just individual shortest edges.'],nspire:['Draw and annotate the network and define the weights.','Use a Calculator or Lists & Spreadsheet page to total candidate paths, trees or odd-vertex pairings.','Record the algorithm choices so the method can be assessed.','Differentiate a demonstrated optimum from a lower/upper bound.'],video:'Calculator'},
 stats:{name:'One-variable statistics and box plots',ti84:['Press STAT → Edit. Enter raw values in L1, or values in L1 and frequencies in L2.','Press STAT → CALC → 1-Var Stats; use L1 and a frequency list only when frequencies are supplied.','Read x̄, n, σx (population) or Sx (sample) as required. Scroll down for quartiles and median.','For a modified box plot: 2nd Y= → Plot1 ON, choose modified box plot, Xlist L1 and frequency 1 or L2. ZOOM → ZoomStat; TRACE identifies quartiles, whiskers and outlier dots.'],nspire:['Add Lists & Spreadsheet, name a column xs and enter data; add a frequency column only when needed.','Use menu → Statistics → Stat Calculations → One-Variable Statistics. Select xs and any frequency list.','Read mean, median, quartiles and the correct sample/population spread.','Add Data & Statistics, choose the variable on the horizontal axis and menu → Plot Type → Box Plot. Inspect individual outliers and quartiles.'],video:'Data and Statistics'},
 probability:{name:'Probability tables and trees',ti84:['Draw the event tree or frequency table first. Label conditional branch probabilities.','Multiply along paths and add mutually exclusive complete paths on the home screen.','For P(A|B), enter the overlap divided by P(B), with brackets around each expression.','A calculator cannot choose the conditioning event for you. Check all probabilities lie in [0,1].'],nspire:['Build the tree or table before calculating.','Use a Calculator page for path products and sums; store intermediate probabilities if useful.','For conditional probability use the event defining the denominator, not the whole original population.','Keep extra digits until the final probability is reported.'],video:'Calculator'},
 binomial:{name:'Binomial pdf, cdf and upper tails',ti84:['Press 2nd VARS (DISTR). Choose binompdf for exactly k, or binomcdf for at most k.','Enter trials n, probability p and count k. Example P(X=3), X~B(10,0.2): binompdf(10,0.2,3).','For P(X≥k), use 1−binomcdf(n,p,k−1). For a≤X≤b, use binomcdf(n,p,b)−binomcdf(n,p,a−1).','State the variable and distribution, then the inequality, calculator expression and probability.'],nspire:['On a Calculator page choose menu → Probability → Distributions → Binomial Pdf or Binomial Cdf.','Pdf asks for n, p and the exact count. Cdf accepts a lower bound and an upper bound.','For P(X≥k), use Cdf from k to n. For a≤X≤b, use bounds a and b directly.','Do not confuse the TI-84 cumulative single-bound convention with the Nspire lower/upper fields.'],video:'Probability Calculations'},
 normal:{name:'Normal cdf and inverse normal',ti84:['Press 2nd VARS → normalcdf. Enter lower, upper, mean μ and standard deviation σ.','Example: normalcdf(42,58,50,8). For a one-sided tail use −1E99 or 1E99 for the remote boundary.','For a percentile use invNorm with left-tail area, μ and σ; on versions offering a tail setting choose it deliberately.','If the model is written N(μ,σ²), enter σ, not σ². normalpdf returns density height rather than an interval probability.'],nspire:['On a Calculator page choose menu → Probability → Distributions → Normal Cdf.','Enter lower bound, upper bound, μ and σ; use ±1E99 for a remote one-sided boundary.','For a percentile choose Inverse Normal and input the area to the left, μ and σ.','Write the shaded interval or percentile in your answer so the probability choice is clear.'],video:'Probability Calculations'},
 test:{name:'Statistical tests and interpretation',ti84:['For a two-independent-sample mean comparison choose STAT → TESTS → 2-SampTTest; choose Data or Stats inputs.','Supply both sample sizes, means and sample standard deviations, or correct raw-data lists. Choose the alternative direction specified. Use Pooled: No unless an equal-variance model is justified.','For a confidence interval choose the interval tool matching the parameter and design; do not substitute a hypothesis-test tool.','Report H₀/H₁, the p-value or interval, the significance level and a conclusion in context.'],nspire:['On a Calculator or Lists & Spreadsheet page use menu → Statistics → Stat Tests → 2-Sample t Test for two independent means.','Choose raw data or summary statistics and the appropriate alternative. Enter sample standard deviations, not variances.','Use the Statistics → Confidence Intervals tools for interval estimates, choosing the appropriate design.','Evaluate assumptions and distinguish fail to reject H₀ from proving it true.'],video:'Data and Statistics'},
 chi:{name:'Chi-squared tests',ti84:['For an independence test enter the observed count table as matrix [A] using 2nd MATRIX → EDIT.','Use STAT → TESTS → χ²-Test, Observed [A] and Expected [B], then Calculate.','For goodness of fit enter observed and expected frequencies in lists and use χ²GOF-Test with appropriate degrees of freedom.','Check expected counts and state the test type, degrees of freedom, p-value and contextual conclusion.'],nspire:['Create the observed matrix or observed/expected lists on a Calculator or Lists & Spreadsheet page.','Use menu → Statistics → Stat Tests → χ² Two-Way Test for independence, or χ² GOF for goodness of fit.','Choose the correct input matrix/lists and degrees of freedom where required.','Verify expected-count assumptions; pool justified categories before recomputing if needed.'],video:'Data and Statistics'},
 derivative:{name:'Numerical differentiation',ti84:['Enter the function in Y1. For a slope at x=a, use MATH → nDeriv and enter the expression, variable X and evaluation point a.','Alternatively graph it, press 2nd TRACE and use dy/dx at the requested input.','Numerical output is a derivative value at one point, not a symbolic derivative formula.','For a tangent, also evaluate the original function for its point; use both in y−y₀=m(x−x₀).'],nspire:['On a Calculator page use menu → Calculus → Numerical Derivative at a Point, or find nDeriv in the Catalog.','Enter the function, variable and point. A non-CAS CX II returns a numerical slope, not a general symbolic derivative.','A Graphs page can display a tangent through its analysis/geometry options; verify the input point.','Write the formula or numerical setup and interpret rate units.'],video:'Graphs'},
 integral:{name:'Definite integration',ti84:['Use MATH → fnInt on the home screen with expression, X, lower bound and upper bound. Example fnInt(2X,X,1,3).','On a graph, 2nd TRACE → ∫f(x)dx also evaluates between chosen bounds.','For geometric area split at zeros or curve intersections if the integrand changes sign.','State the integrand, bounds, value and units. The 2029 SL trapezoidal-rule topic is not included.'],nspire:['On a Calculator page use menu → Calculus → Numerical Integral, or the definite-integral template.','Supply variable, lower/upper bounds and the integrand; a non-CAS CX II evaluates a definite integral numerically.','For area between curves integrate upper minus lower and split where the order changes.','Show the integral in your written method, rather than just a calculator result.'],video:'Calculator'}
};
const TI_VIDEOS={ti84:'https://education.ti.com/en/product-resources/product-video-tutorials/ti-84plus-ce-tutorials',nspire:'https://education.ti.com/en/product-resources/product-video-tutorials/ti-nspire-cx-tutorials'};
